@@ -0,0 +1,13 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortByStartsAt(items, startsAtOf = (item) => item.startsAt) {
+  return items
+    .map((item, index) => ({ item, index, time: new Date(startsAtOf(item)).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ item }) => item);
+}
+
+export function buildAgenda(events) {
+  const entries = events.map((event) => ({ card: createEventCard(event), startsAt: event.startsAt }));
+  return sortByStartsAt(entries).map(({ card }) => card);
+}

